mapper.select:
select e.exam_id, e.exam_name, e.paper_id, ifnull(nullif(e.paper_name, ''), p.paper_name) as paper_name, e.record_id, e.attendee_source, e.retake_from_id, e.retake_count, e.score_strategy, e.start_time, e.end_time, e.exam_status, e.publish_by, e.publish_time, e.dept_id, e.enterprise_id, e.del_flag, e.create_by, e.create_time, e.update_by, e.update_time, e.remark, s.total_cnt, s.submitted_cnt, s.absent_cnt, s.pass_rate, s.avg_score from biz_safety_exam e left join biz_safety_exam_paper p on p.paper_id = e.paper_id and p.del_flag = '0' left join ( select exam_id, count(*) as total_cnt, sum(case when exam_result in ('2', '4') then 1 else 0 end) as submitted_cnt, sum(case when exam_result = '3' then 1 else 0 end) as absent_cnt, round(sum(case when exam_result in ('2', '4') and is_pass = '1' then 1 else 0 end) * 100.0 / nullif(sum(case when exam_result in ('2', '4') then 1 else 0 end), 0), 1) as pass_rate, round(avg(case when exam_result in ('2', '4') then total_score end), 1) as avg_score from biz_safety_exam_record where del_flag = '0' group by exam_id ) s on s.exam_id = e.exam_id
e.del_flag = '0' AND e.exam_name like concat('%', #{examName}, '%') AND e.paper_id = #{paperId} AND e.record_id = #{recordId} AND e.exam_status = #{examStatus} AND e.start_time >= #{params.beginTime} AND e.end_time <= #{params.endTime} AND ${params.dataScope}
order by e.exam_id desc

mapper.update:
update biz_safety_exam
exam_name = #{examName}, paper_id = #{paperId}, paper_name = #{paperName}, record_id = #{recordId}, attendee_source = #{attendeeSource}, retake_from_id = #{retakeFromId}, retake_count = #{retakeCount}, score_strategy = #{scoreStrategy}, start_time = #{startTime}, end_time = #{endTime}, exam_status = #{examStatus}, publish_by = #{publishBy}, publish_time = #{publishTime}, dept_id = #{deptId}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
where exam_id = #{examId}
